@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Outfit:wght@400;500;600;700;800;900&display=swap');
:root{--ink:#071b26;--cream:#fff8e9;--orange:#ff713d;--yellow:#ffd65a;--mint:#a8ffcb;--mono:'DM Mono',monospace;--display:'Outfit',sans-serif}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101b22;color:white;font-family:var(--display);user-select:none;-webkit-user-select:none}body{display:grid;place-items:center}.game-shell{position:relative;width:min(100vw,160vh);height:min(100vh,62.5vw);min-height:360px;overflow:hidden;background:#8be3ed;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.topbar{position:absolute;z-index:2;top:0;left:0;right:0;height:68px;padding:0 4.2%;display:flex;align-items:center;justify-content:space-between;color:#12313b;background:linear-gradient(180deg,rgba(255,249,230,.93),rgba(255,249,230,.75));border-bottom:1px solid rgba(22,65,68,.08)}.brand{font-weight:900;letter-spacing:.1em;font-size:17px;display:flex;align-items:center;gap:10px}.brand-mark{display:grid;place-items:center;width:27px;height:27px;border-radius:9px;color:#fff;background:#ff7043;font-size:16px;box-shadow:0 4px 10px #e95f3760}.brand-light{font-weight:500;opacity:.65}.track-pill{font:500 10px var(--mono);letter-spacing:.1em;display:flex;align-items:center;gap:9px;color:#48646a}.track-pill b{color:#12313b;font-weight:500}.live-dot{width:7px;height:7px;background:#ff754b;border-radius:50%;box-shadow:0 0 0 4px #ff754b24}.pill-divider{opacity:.35}.sound-button{border:1px solid #173b442b;background:#ffffff75;color:#173b44;padding:8px 11px;border-radius:9px;font:600 13px var(--display);cursor:pointer}.sound-button span{font:500 9px var(--mono);letter-spacing:.08em;margin-left:4px}.hud{position:absolute;z-index:2;top:87px;left:4.2%;display:flex;align-items:center;gap:22px;color:#102e36;text-shadow:0 1px 5px #fff8}.race-info{display:flex;flex-direction:column;align-items:center;min-width:55px}.position{font-size:41px;line-height:.95;font-weight:900;letter-spacing:-.08em}.position span{font-size:17px;color:#ff7043;vertical-align:top;letter-spacing:0}.race-label,.eyebrow,.coin-counter small{font:500 8px var(--mono);letter-spacing:.14em;color:#35616a}.lap-info,.timer{display:flex;flex-direction:column;gap:1px}.lap-info strong,.timer strong{font:500 16px var(--mono);letter-spacing:-.06em}.lap-info strong span{font-size:10px;color:#658089}.lap-track{width:74px;height:3px;margin-top:6px;border-radius:2px;background:#20495326;overflow:hidden}.lap-track i{height:100%;width:0;display:block;background:#ff7043;transition:width .1s}.timer strong{font-size:14px}.coin-counter{display:grid;grid-template-columns:18px auto;grid-template-rows:19px 10px;align-items:center;column-gap:4px}.coin-icon{grid-row:1;color:#ffba29;text-shadow:0 1px #a66300;font-size:15px}.coin-counter strong{font:500 14px var(--mono)}.coin-counter small{grid-column:2;font-size:7px}.item-box{width:48px;height:50px;margin-left:3px;background:#fffbecdd;border:1px solid #ffffff;border-radius:12px;box-shadow:0 5px 16px #163c3b25;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;transform:rotate(-4deg)}.item-icon{width:24px;height:25px;display:grid;place-items:center;color:#fff;background:linear-gradient(145deg,#8b73ee,#f35a9a);border-radius:7px;font-size:17px;font-weight:900}.item-box span{font:500 7px var(--mono);color:#516870}.speedometer{position:absolute;z-index:2;right:4.4%;bottom:8%;color:white;text-align:right;text-shadow:0 2px 8px #18342c66}.speed-number{font:500 42px/.9 var(--mono);letter-spacing:-.1em}.speed-unit{font:500 9px var(--mono);letter-spacing:.14em;margin-top:5px}.speed-arc{height:3px;width:80px;margin:9px 0 0 auto;background:#ffffff5b;border-radius:3px;overflow:hidden}.speed-arc i{display:block;width:0;height:100%;background:#ffdf68;transition:width .1s}.controls-hint{position:absolute;z-index:2;bottom:25px;left:50%;transform:translateX(-50%);white-space:nowrap;color:#fffde8;text-shadow:0 2px 5px #173a4180;font:500 9px var(--mono);letter-spacing:.09em}.controls-hint>span{display:inline-grid;place-items:center;width:20px;height:20px;border:1px solid #ffffffa6;border-radius:5px;margin-right:3px;font-size:12px}.controls-hint i{font-style:normal;opacity:.55;margin:0 6px}.controls-hint kbd{font:500 8px var(--mono);padding:4px 6px;border:1px solid #ffffffa6;border-radius:4px}.bottom-note{position:absolute;z-index:2;bottom:0;left:0;right:0;height:29px;padding:0 4.2%;background:#fff8e9dc;color:#31535a;display:flex;align-items:center;gap:8px;font:500 8px var(--mono);letter-spacing:.12em}.bottom-note>span{color:#ff9e38;font-size:12px}.bottom-note i{opacity:.4;font-style:normal}.footer-right{margin-left:auto;color:#527078}.footer-right b{font-size:7px}.screen-overlay{position:absolute;z-index:5;inset:0;display:flex;align-items:center;justify-content:flex-start;padding:95px 0 50px 9%;background:linear-gradient(90deg,rgba(6,27,34,.68),rgba(6,27,34,.17) 58%,transparent);transition:opacity .4s,visibility .4s}.screen-overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.start-card{width:365px;color:var(--cream);text-shadow:0 2px 9px #0a2939aa}.card-kicker,.result-kicker{font:500 9px var(--mono);letter-spacing:.14em;color:#ffe27b}.card-kicker span{font-size:12px;color:#ff7649;margin-right:5px}.start-card h1{font-size:clamp(52px,7vw,86px);font-weight:900;line-height:.78;letter-spacing:-.065em;margin:19px 0 18px}.start-card h1 em{font-style:normal;color:#ffda69}.start-card p{max-width:320px;color:#fff6df;font-size:13px;line-height:1.55;margin:0 0 20px}.race-meta{display:flex;gap:23px;margin-bottom:20px}.race-meta div{display:grid;grid-template-columns:22px auto;grid-template-rows:18px 12px;align-items:center;column-gap:4px}.race-meta span{grid-row:1/3;font-size:17px}.race-meta b{font:500 14px var(--mono)}.race-meta small{font:400 7px var(--mono);letter-spacing:.1em;color:#e3ddc5}.primary-button{position:relative;display:flex;align-items:center;justify-content:space-between;width:235px;padding:14px 16px;border:0;border-radius:8px;background:#ff7444;color:white;font:700 11px var(--display);letter-spacing:.09em;box-shadow:0 8px 22px #ef603b55;cursor:pointer;transition:transform .15s,background .15s}.primary-button:hover{transform:translateY(-2px);background:#ff8557}.primary-button span{font-size:18px;line-height:10px}.start-controls{display:flex;gap:13px;margin-top:19px;color:#fffbeb;font:400 7px var(--mono);letter-spacing:.035em}.start-controls b{font-size:8px}.side-note{position:absolute;right:4.5%;bottom:48px;display:flex;align-items:center;gap:10px;color:#fff8df;font:500 8px var(--mono);letter-spacing:.14em}.side-note i{width:35px;height:1px;background:#fff8df88}.result-card{width:390px;padding:28px 30px;background:#fff8e9f2;color:#12313b;border:1px solid #fff;border-radius:18px;box-shadow:0 22px 80px #09253066;text-shadow:none}.result-kicker{color:#f27048}.result-card h2{margin:9px 0 2px;font-size:37px;line-height:1;letter-spacing:-.06em;font-weight:900}.result-card>p{font-size:12px;color:#567078}.result-stats{display:flex;gap:32px;padding:17px 0 20px;margin:12px 0 15px;border-top:1px solid #17414b18;border-bottom:1px solid #17414b18}.result-stats div{display:flex;flex-direction:column;gap:5px}.result-stats span{font:500 7px var(--mono);letter-spacing:.1em;color:#637c80}.result-stats b{font:600 16px var(--mono)}.result-card .primary-button{width:100%}.race-toast{position:absolute;z-index:3;top:23%;left:50%;transform:translate(-50%,-10px);opacity:0;color:#fff3bb;font-weight:900;font-size:22px;letter-spacing:.04em;text-shadow:0 3px 8px #183a43;transition:opacity .2s,transform .2s;pointer-events:none}.race-toast.show{opacity:1;transform:translate(-50%,0)}.countdown{position:absolute;z-index:3;top:36%;left:50%;transform:translate(-50%,-50%);font-size:clamp(70px,12vw,135px);font-weight:900;line-height:1;color:#fff3a0;text-shadow:0 5px 0 #f4774c,0 12px 30px #173d4a;pointer-events:none}.center-message{position:absolute;z-index:3;top:43%;left:50%;transform:translate(-50%,-50%);font-size:clamp(30px,6vw,65px);font-weight:900;color:#fff2a1;text-shadow:0 4px 0 #ed6940,0 8px 25px #173d4a;pointer-events:none}.touch-controls{display:none;position:absolute;z-index:4;bottom:38px;left:0;right:0;justify-content:space-between;align-items:flex-end;padding:0 5%;pointer-events:none}.touch-controls button{pointer-events:auto;color:#fff;border:1px solid #ffffff85;background:#092d38a8;backdrop-filter:blur(4px);border-radius:50%;width:56px;height:56px;font:700 17px var(--display);touch-action:none}.touch-steer,.touch-drive{display:flex;gap:10px}.touch-drive{align-items:flex-end}.touch-drive button{width:50px;height:50px;font-size:11px}.touch-drive .accelerate{width:64px;height:64px;border-color:#ffe781;background:#ff7544c9;font-size:24px}.touch-controls button.active{background:#ff7544;transform:scale(.94)}
@media(max-width:700px){.game-shell{width:100vw;height:100dvh;min-height:0}.topbar{height:55px;padding:0 15px}.brand{font-size:13px;gap:7px}.brand-mark{width:23px;height:23px}.track-pill{font-size:7px;gap:5px}.track-pill b{display:none}.sound-button{padding:7px 8px}.sound-button span{display:none}.hud{top:68px;left:14px;gap:13px}.position{font-size:35px}.race-label{font-size:7px}.lap-info strong{font-size:13px}.lap-track{width:54px}.timer strong{font-size:12px}.timer .eyebrow,.lap-info .eyebrow{font-size:7px}.coin-counter{display:none}.item-box{width:42px;height:43px}.speedometer{right:18px;bottom:130px}.speed-number{font-size:34px}.controls-hint{display:none}.touch-controls{display:flex}.bottom-note{height:26px;padding:0 14px;font-size:7px}.screen-overlay{padding:68px 0 50px 7%;align-items:center;background:linear-gradient(90deg,rgba(6,27,34,.72),rgba(6,27,34,.28) 72%,transparent)}.start-card{width:min(340px,88vw)}.start-card h1{font-size:clamp(56px,15vw,80px);margin:15px 0}.start-card p{font-size:12px;max-width:270px;margin-bottom:15px}.race-meta{margin-bottom:16px}.side-note{display:none}.start-controls{gap:9px;font-size:6px}.start-controls b{font-size:7px}.primary-button{width:220px;padding:13px}.result-card{width:88vw;padding:24px}.result-card h2{font-size:32px}.result-stats{gap:22px}.result-stats b{font-size:14px}.race-toast{top:21%;font-size:18px}}
@media(max-height:500px) and (min-width:701px){.topbar{height:52px}.hud{top:62px}.start-card h1{font-size:55px;margin:11px 0}.start-card p{margin-bottom:12px}.race-meta{margin-bottom:12px}.screen-overlay{padding-top:55px}.start-controls{margin-top:12px}.bottom-note{height:22px}.speedometer{bottom:7%}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = { start: $('startScreen'), result: $('resultScreen'), startBtn: $('startButton'), again: $('againButton'), hud: $('hud'), position: $('position'), lap: $('lap'), lapProgress: $('lapProgress'), timer: $('timer'), coins: $('coins'), item: $('itemBox'), speed: $('speed'), speedArc: $('speedArc'), countdown: $('countdown'), message: $('centerMessage'), toast: $('toast') };
  const TAU = Math.PI * 2, LAP_LENGTH = 11500, TOTAL_LAPS = 3, MAX_SPEED = 245;
  let W = 1280, H = 720, dpr = 1, last = 0, running = false, startedAt = 0, elapsed = 0, raf = 0;
  let player, racers, objects, keys = {}, touch = {}, audio = null, soundOn = false, toastTime = 0;
  const racerNames = ['Luna', 'Tito', 'Nina', 'Bento', 'Zeca', 'Maya', 'Você'];
  const palette = ['#f25a48','#56a7f2','#f3bf36','#a374e8','#45c995','#ef80ba','#e3edf0'];
  function resize(){
    const r = canvas.getBoundingClientRect(); dpr = Math.min(devicePixelRatio || 1, 1.7); W = r.width; H = r.height;
    canvas.width = Math.round(W*dpr); canvas.height = Math.round(H*dpr); ctx.setTransform(dpr,0,0,dpr,0,0);
  }
  window.addEventListener('resize', resize); resize();
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const mix=(a,b,t)=>a+(b-a)*t;
  const hash=(n)=>{let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)};
  function reset(){
    player={distance:0,lane:0,speed:0,coins:0,item:null,drift:0,boost:0,invuln:0,finished:false};
    racers=Array.from({length:7},(_,i)=>({name:racerNames[i],color:palette[i],distance:-i*28-30, lane:(i%2?-.32:.32), speed:0,phase:hash(i+3)*TAU, finished:false}));
    objects=[];
    for(let n=0;n<68;n++){
      const base=220+n*495;
      if(n%3!==1) objects.push({type:'coin',distance:base+90,lane:(hash(n+70)-.5)*1.25,used:false});
      if(n%4===0) objects.push({type:'box',distance:base+305,lane:(hash(n+20)-.5)*1.25,used:false});
    }
    elapsed=0;startedAt=0;last=0;running=false;toastTime=0;
    ui.position.innerHTML='1<span>º</span>';ui.lap.innerHTML='1<span> / 3</span>';ui.lapProgress.style.width='0%';ui.coins.textContent='00';ui.speed.textContent='000';ui.speedArc.style.width='0%';ui.item.querySelector('.item-icon').textContent='?';
    ui.countdown.textContent='';ui.message.textContent='';ui.result.classList.add('hidden');ui.start.classList.remove('hidden');
    draw(0);
  }
  function curve(s){return Math.sin(s/1650)*155 + Math.sin(s/610)*58 + Math.sin(s/3550)*120;}
  function roadCenter(ahead){return W*.5 + (curve(player.distance+ahead)-curve(player.distance)) * (W/1280);}
  function project(depth){const horizon=H*.405;const t=1/(1+Math.max(0,depth)/760);return {y:horizon+(H-horizon)*t,scale:t};}
  function sky(){
    const g=ctx.createLinearGradient(0,0,0,H*.57);g.addColorStop(0,'#68cce5');g.addColorStop(.58,'#b7edf0');g.addColorStop(1,'#ffe9bd');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    // warm sun and hazy island horizon
    const sunX=W*.77,sunY=H*.22,sunR=Math.min(W,H)*.055;
    let glow=ctx.createRadialGradient(sunX,sunY,2,sunX,sunY,sunR*2.7);glow.addColorStop(0,'#fff4bfaa');glow.addColorStop(1,'#fff4bf00');ctx.fillStyle=glow;ctx.fillRect(sunX-sunR*3,sunY-sunR*3,sunR*6,sunR*6);ctx.fillStyle='#fff4c9';ctx.beginPath();ctx.arc(sunX,sunY,sunR,0,TAU);ctx.fill();
    // distant ocean
    ctx.fillStyle='#4dbdca';ctx.fillRect(0,H*.35,W,H*.16);
    ctx.fillStyle='#8cdbd7';ctx.fillRect(0,H*.35,W,H*.028);
    for(let i=0;i<5;i++){let x=((i*317+player.distance*.027)%(W+120))-60,y=H*(.16+(i%3)*.06);cloud(x,y,.8+(i%2)*.35)}
    // layered tropical hills
    hill('#82cdb0',.385,145,260,player.distance*.012);hill('#479f89',.418,110,220,player.distance*.018);hill('#25786e',.447,74,175,player.distance*.024);
  }
  function cloud(x,y,s){ctx.save();ctx.globalAlpha=.6;ctx.fillStyle='#fff9e9';ctx.beginPath();ctx.ellipse(x,y,34*s,10*s,0,0,TAU);ctx.ellipse(x-15*s,y+1*s,15*s,10*s,0,0,TAU);ctx.ellipse(x+8*s,y-6*s,18*s,14*s,0,0,TAU);ctx.ellipse(x+24*s,y,15*s,9*s,0,0,TAU);ctx.fill();ctx.restore()}
  function hill(color,base,amp,period,offset){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(0,H*base);for(let x=0;x<=W+10;x+=12){let y=H*base-Math.sin((x+offset)/period)*amp*(H/720);ctx.lineTo(x,y)}ctx.lineTo(W,H*.54);ctx.lineTo(0,H*.54);ctx.closePath();ctx.fill()}
  function drawRoad(){
    const horizon=H*.405;ctx.fillStyle='#64bd83';ctx.fillRect(0,horizon,W,H-horizon);
    const depths=[];for(let i=0;i<=70;i++){let t=i/70;depths.push(5600*(1-t)*(1-t))}depths.reverse();
    for(let i=0;i<depths.length-1;i++){
      const far=depths[i],near=depths[i+1],pf=project(far),pn=project(near),cf=roadCenter(far),cn=roadCenter(near);
      const wf=(W*.47)*pf.scale,wn=(W*.47)*pn.scale;
      const stripe=Math.floor((player.distance+near)/170)%2;
      ctx.fillStyle=stripe?'#60ba7d':'#68c583';ctx.fillRect(0,pn.y,W,pf.y-pn.y+1);
      // shoulder and candy curbs
      ctx.fillStyle='#f7f0d7';ctx.beginPath();ctx.moveTo(cf-wf*1.12,pf.y);ctx.lineTo(cf+wf*1.12,pf.y);ctx.lineTo(cn+wn*1.12,pn.y);ctx.lineTo(cn-wn*1.12,pn.y);ctx.closePath();ctx.fill();
      ctx.fillStyle=stripe?'#f05f50':'#fff0cc';ctx.beginPath();ctx.moveTo(cf-wf*1.08,pf.y);ctx.lineTo(cf-wf*.99,pf.y);ctx.lineTo(cn-wn*.99,pn.y);ctx.lineTo(cn-wn*1.08,pn.y);ctx.closePath();ctx.fill();
      ctx.beginPath();ctx.moveTo(cf+wf*.99,pf.y);ctx.lineTo(cf+wf*1.08,pf.y);ctx.lineTo(cn+wn*1.08,pn.y);ctx.lineTo(cn+wn*.99,pn.y);ctx.closePath();ctx.fill();
      ctx.fillStyle=i%2?'#8f9687':'#9ba092';ctx.beginPath();ctx.moveTo(cf-wf*.99,pf.y);ctx.lineTo(cf+wf*.99,pf.y);ctx.lineTo(cn+wn*.99,pn.y);ctx.lineTo(cn-wn*.99,pn.y);ctx.closePath();ctx.fill();
      // intermittent center dash
      if(Math.floor((player.distance+near)/440)%2===0){ctx.fillStyle='#fff3d4';const dw=wn*.012;ctx.beginPath();ctx.moveTo(cf-dw,pf.y);ctx.lineTo(cf+dw,pf.y);ctx.lineTo(cn+dw,pn.y);ctx.lineTo(cn-dw,pn.y);ctx.fill()}
    }
    drawScenery();drawTrackObjects();drawRacers();
  }
  function drawScenery(){
    const horizon=H*.405;
    for(let i=0;i<17;i++){
      const absolute=Math.floor(player.distance/230)*230 + i*230;
      const ahead=absolute-player.distance;if(ahead<0||ahead>5200)continue;
      const p=project(ahead),side=i%2?-1:1,variation=hash(Math.floor(absolute/230));
      const center=roadCenter(ahead),roadW=W*.47*p.scale;
      const x=center+side*(roadW*(1.22+variation*.35)+48*p.scale),y=p.y;
      if(y<horizon||y>H+30)continue;
      drawPalm(x,y,p.scale,hash(i+81)>.5?0:1);
    }
    // occasional flags and spectator patches nearer the track
    for(let i=0;i<6;i++){
      const ahead=((i*800+520-player.distance%4800+4800)%4800);if(ahead<80||ahead>2100)continue;
      const p=project(ahead),c=roadCenter(ahead),rw=W*.47*p.scale,side=i%2?1:-1,x=c+side*rw*1.18;
      ctx.fillStyle='#f9e9be';ctx.fillRect(x-18*p.scale,p.y-13*p.scale,36*p.scale,8*p.scale);
      ctx.fillStyle=i%2?'#f47755':'#5cbbaa';ctx.fillRect(x-18*p.scale,p.y-13*p.scale,12*p.scale,8*p.scale);
    }
  }
  function drawPalm(x,y,s,kind){
    const size=clamp(s,0,1.35),trunk=76*size;
    ctx.save();ctx.translate(x,y);ctx.strokeStyle='#795843';ctx.lineWidth=Math.max(1,7*size);ctx.beginPath();ctx.moveTo(0,0);ctx.quadraticCurveTo(-3*size,-trunk*.55,4*size,-trunk);ctx.stroke();
    const crownY=-trunk,leaf=26*size;
    for(let i=0;i<6;i++){const a=i*TAU/6+kind*.3;ctx.strokeStyle=['#15765f','#21876a','#30956c'][i%3];ctx.lineWidth=Math.max(1,5*size);ctx.lineCap='round';ctx.beginPath();ctx.moveTo(4*size,crownY);ctx.quadraticCurveTo(Math.cos(a)*leaf*.55,crownY+Math.sin(a)*leaf*.25,Math.cos(a)*leaf*1.9,crownY+Math.sin(a)*leaf*.9+9*size);ctx.stroke()}
    ctx.fillStyle='#f1a94d';ctx.beginPath();ctx.arc(4*size,crownY+3*size,4*size,0,TAU);ctx.fill();ctx.restore();
  }

input.newString:
  ctx.fillStyle='#f1a94d';ctx.beginPath();ctx.arc(4*size,crownY+3*size,4*size,0,TAU);ctx.fill();ctx.restore();
}
function drawTrackObjects(){
  for(const o of objects){if(o.used)continue;const ahead=o.distance-player.distance;if(ahead<35||ahead>5200)continue;const p=project(ahead),c=roadCenter(ahead),rw=W*.47*p.scale,x=c+o.lane*rw*.72,y=p.y-14*p.scale;
    if(o.type==='coin'){
      const pulse=1+Math.sin(elapsed*5+o.distance)*.1,r=Math.max(2,9*p.scale*pulse);ctx.fillStyle='#e99c2a';ctx.beginPath();ctx.ellipse(x,y+2*p.scale,r*1.1,r,0,0,TAU);ctx.fill();ctx.fillStyle='#ffe272';ctx.beginPath();ctx.ellipse(x,y,r*.75,r*.9,0,0,TAU);ctx.fill();ctx.fillStyle='#fff5bc';ctx.fillRect(x-r*.16,y-r*.55,r*.3,r*1.1);
    }else{
      const w=Math.max(8,29*p.scale),h=w;ctx.save();ctx.translate(x,y);ctx.rotate(elapsed*1.25);ctx.fillStyle='#fff1ab';ctx.strokeStyle='#ffffff';ctx.lineWidth=Math.max(1,2*p.scale);ctx.beginPath();ctx.roundRect(-w/2,-h/2,w,h,4*p.scale);ctx.fill();ctx.stroke();ctx.fillStyle='#ea70af';ctx.font=`900 ${Math.max(8,w*.65)}px Outfit`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('?',0,1);ctx.restore();
    }
  }
}
function drawRacers(){
  const visible=racers.filter(r=>!r.finished).map(r=>({r,depth:r.distance-player.distance})).filter(o=>o.depth>45&&o.depth<2600).sort((a,b)=>b.depth-a.depth);
